PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS `clients` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  `name` TEXT NOT NULL,
  `document` TEXT,
  `logo_url` TEXT,
  `primary_color` TEXT DEFAULT '#302d91' NOT NULL,
  `secondary_color` TEXT DEFAULT '#d63a1f' NOT NULL,
  `accent_color` TEXT DEFAULT '#ffffff' NOT NULL,
  `active` INTEGER DEFAULT 1 NOT NULL,
  `created_at` TEXT NOT NULL,
  `updated_at` TEXT NOT NULL
);

INSERT OR IGNORE INTO `clients` (`id`,`name`,`document`,`logo_url`,`primary_color`,`secondary_color`,`accent_color`,`active`,`created_at`,`updated_at`)
VALUES (1,'Decorlit',NULL,'data:image/png;base64,','#302d91','#d63a1f','#ffffff',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS `user_clients` (
  `user_id` INTEGER NOT NULL,
  `client_id` INTEGER NOT NULL,
  `created_at` TEXT NOT NULL,
  PRIMARY KEY (`user_id`,`client_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`client_id`) REFERENCES `clients`(`id`) ON DELETE CASCADE
);

INSERT OR IGNORE INTO `user_clients` (`user_id`,`client_id`,`created_at`)
SELECT `id`,1,CURRENT_TIMESTAMP FROM `users`;

ALTER TABLE `silos` ADD COLUMN `client_id` INTEGER NOT NULL DEFAULT 1;
ALTER TABLE `audits` ADD COLUMN `client_id` INTEGER NOT NULL DEFAULT 1;

CREATE INDEX IF NOT EXISTS `silos_client_idx` ON `silos` (`client_id`);
CREATE INDEX IF NOT EXISTS `audits_client_idx` ON `audits` (`client_id`);
CREATE INDEX IF NOT EXISTS `user_clients_client_idx` ON `user_clients` (`client_id`);

CREATE TRIGGER IF NOT EXISTS `silos_client_insert_guard`
BEFORE INSERT ON `silos`
WHEN NOT EXISTS (SELECT 1 FROM `clients` WHERE `id` = NEW.`client_id`)
BEGIN SELECT RAISE(ABORT, 'Cliente inválido'); END;
CREATE TRIGGER IF NOT EXISTS `silos_client_update_guard`
BEFORE UPDATE OF `client_id` ON `silos`
WHEN NOT EXISTS (SELECT 1 FROM `clients` WHERE `id` = NEW.`client_id`)
BEGIN SELECT RAISE(ABORT, 'Cliente inválido'); END;
